    #[Override]
    public function resolve(ThemeRef $ref): ?Theme
    {
        if ($ref instanceof Theme) {
            return $ref;
        } elseif (!$ref->_private_resolve) {
            $ref->_private_resolve = $this->conn->retrieve(new ThemeFilter(uids: [ $ref->uid() ]));
        }
        return $ref->_private_resolve;
